class ScrumMaster:
    def act(self, blocker: str) -> str:
        return f"removing impediment: {blocker}"


class ProductOwner:
    def __init__(self):
        self.backlog = []

    def add_item(self, name: str, value: int) -> None:
        self.backlog.append((name, value))

    def top_priority(self) -> str:
        return max(self.backlog, key=lambda item: item[1])[0]


class DevelopmentTeam:
    def __init__(self, members: int):
        self.members = members

    def can_start(self, story_points: int) -> bool:
        return story_points <= self.members * 5


sm = ScrumMaster()
po = ProductOwner()
po.add_item("login", 8)
po.add_item("dashboard", 13)
po.add_item("logout", 3)
dev = DevelopmentTeam(members=5)

print(sm.act("staging environment is down"))
print(f"top priority: {po.top_priority()}")
print(f"team can start 13-point story: {dev.can_start(13)}")
print(f"team can start 30-point story: {dev.can_start(30)}")
